import { Database, type SQLQueryBindings, type Statement } from "bun:sqlite";

interface NativeStatement {
  finalize(): void;
}

interface StatementReference {
  wrapper: WeakRef<Statement>;
  native: WeakRef<NativeStatement>;
}

/** Factory-owned connection. Native methods retain their usual signatures.
 * Weak tracking finds live statements at explicit close without keeping
 * otherwise discarded statements alive for the connection's entire lifetime.
 */
export class OwnedDatabase extends Database {
  private readonly statements = new Set<StatementReference>();
  private readonly collected = new FinalizationRegistry<StatementReference>(reference => {
    this.statements.delete(reference);
  });

  override prepare<Result, Params extends SQLQueryBindings | SQLQueryBindings[]>(
    sql: string,
    params?: Params,
    flags?: number,
  ): Statement<Result, Params extends any[] ? Params : [Params]> {
    // Bun's query/transaction implementations also supply an internal third
    // flags argument, although it is absent from the public 1.3.14 typings.
    const statement = Reflect.apply(super.prepare, this, [sql, params, flags]) as
      Statement<Result, Params extends any[] ? Params : [Params]>;
    // The JS wrapper can be collected before the native resource. Keep weak
    // references to both and retire tracking only when the native object dies.
    const native = statement.native as NativeStatement;
    const reference: StatementReference = {
      wrapper: new WeakRef<Statement>(statement),
      native: new WeakRef(native),
    };
    this.statements.add(reference);
    this.collected.register(native, reference, reference);
    return statement;
  }

  /** Attempt every live finalizer. Keep failures reachable for a later retry. */
  finalizeStatements(): void {
    const failures: unknown[] = [];
    for (const reference of this.statements) {
      const statement = reference.wrapper.deref();
      try {
        if (statement) statement.finalize();
        else reference.native.deref()?.finalize();
        this.statements.delete(reference);
        this.collected.unregister(reference);
      } catch (error) {
        failures.push(error);
      }
    }
    if (failures.length > 0) {
      throw new AggregateError(failures, "Database statement finalization failed; connection retained for retry");
    }
  }
}

/**
 * Database Connection and Initialization
 *
 * Provides SQLite database initialization with WAL mode,
 * performance pragmas, busy timeout, integrity checks, and FTS5 verification.
 */

import type { Database } from "bun:sqlite";
import { OwnedDatabase } from "./owned-database.js";
import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { createSchema, checkFts5Support } from "./schema.js";
import { ErrorCode, MemoryError } from "../../domain/index.js";
import { getDbPath as pathsGetDbPath } from "../paths.js";
import { unknownErrorMessage } from "../../domain/errors/unknown-error.js";

/**
 * Database configuration options
 */
export interface DatabaseConfig {
    /** Path to the database file. Use ":memory:" for in-memory database. */
    path: string;
    /** Whether to create the database if it doesn't exist. Default: true */
    create?: boolean;
    /** Whether to apply schema on initialization. Default: true */
    applySchema?: boolean;
    /** Whether to enable WAL mode. Default: true */
    walMode?: boolean;
    /** Cache size in KB (negative) or pages (positive). Default: -64000 (64MB) */
    cacheSize?: number;
    /** Busy timeout in milliseconds for handling database locks. Default: 5000 */
    busyTimeout?: number;
    /** Whether to run quick integrity check on startup. Default: true for file DB, false for :memory: */
    quickCheck?: boolean;
}

/**
 * Result of database initialization
 */
export interface DatabaseInitResult {
    /** The initialized database instance */
    db: Database;
    /** Whether WAL mode was successfully enabled */
    walEnabled: boolean;
    /** Whether FTS5 extension is available */
    fts5Available: boolean;
    /** Whether sqlite-vec extension is loaded (vector search available) */
    sqliteVecAvailable: boolean;
}

/**
 * Attempt to load the sqlite-vec extension into a database.
 *
 * sqlite-vec enables vector similarity search via vec0 virtual tables.
 * If the extension is not available (e.g., not installed), this returns false
 * and the database continues to work with FTS5-only search.
 *
 * @param db - Database instance to load the extension into
 * @returns true if loaded successfully, false otherwise
 */
export function loadSqliteVecExtension(db: Database): boolean {
    try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const sqliteVec = require("sqlite-vec");
        sqliteVec.load(db);
        return true;
    } catch {
        // sqlite-vec not available -- vector search will be disabled
        return false;
    }
}

/**
 * Get the default database path
 *
 * @returns Path to the database file
 */
export function getDefaultDbPath(): string {
    return pathsGetDbPath();
}

/**
 * Initialize a SQLite database with optimal settings
 *
 * Configures:
 * - Foreign keys enabled
 * - WAL mode (for file-based databases)
 * - Performance pragmas (synchronous, cache_size, temp_store)
 * - FTS5 support verification
 * - Schema creation (optional)
 *
 * @param config - Database configuration options
 * @returns Database instance with initialization status
 * @throws Error if FTS5 is not available
 *
 * @example
 * ```typescript
 * // In-memory database
 * const { db } = initializeDatabase({ path: ":memory:" });
 *
 * // File-based database with custom cache
 * const { db, walEnabled } = initializeDatabase({
 *     path: "./data/memory.db",
 *     cacheSize: -32000  // 32MB
 * });
 * ```
 */
export function initializeDatabase(config: DatabaseConfig): DatabaseInitResult {
    const {
        path,
        create = true,
        applySchema = true,
        walMode = true,
        cacheSize = -64000,
        busyTimeout = 5000,
    } = config;

    // Determine quickCheck default: true for file DB (if exists), false for :memory:
    const isFileDb = path !== ":memory:";
    const fileExists = isFileDb && existsSync(path);
    const quickCheck = config.quickCheck ?? (isFileDb && fileExists);

    // Ensure directory exists for file-based databases
    if (isFileDb) {
        try {
            mkdirSync(dirname(path), { recursive: true });
        } catch (error) {
            const message = unknownErrorMessage(error);
            throw new MemoryError(
                ErrorCode.DB_CONNECTION_FAILED,
                `Failed to create database directory: ${message}`,
                { path: dirname(path) }
            );
        }
    }

    // Create database connection
    let db: Database;
    try {
        db = new OwnedDatabase(path, { create, readwrite: true });
    } catch (error) {
        const message = unknownErrorMessage(error);
        const errno = (error as NodeJS.ErrnoException).code;
        throw new MemoryError(
            ErrorCode.DB_CONNECTION_FAILED,
            `Failed to connect to database: ${message}`,
            { path, ...(errno ? { errno } : {}) }
        );
    }

    // Helper to handle corrupted file errors
    const handleDbError = (error: unknown): never => {
        closeDatabase(db);
        const message = unknownErrorMessage(error);
        // "file is not a database" or similar indicates corruption
        if (message.includes("not a database") || message.includes("SQLITE_NOTADB")) {
            throw new MemoryError(
                ErrorCode.DB_CORRUPTED,
                "Database file is corrupted or not a valid SQLite database",
                { path }
            );
        }
        throw new MemoryError(
            ErrorCode.DB_CONNECTION_FAILED,
            `Failed to initialize database: ${message}`,
            { path }
        );
    };

    try {
        // Enable foreign keys - this also validates the database file
        db.exec("PRAGMA foreign_keys = ON;");

        // Configure WAL mode
        let walEnabled = false;
        if (walMode && isFileDb) {
            db.exec("PRAGMA journal_mode = WAL;");
            const result = db.query("PRAGMA journal_mode;").get() as { journal_mode: string };
            walEnabled = result.journal_mode === "wal";
            if (!walEnabled) {
                console.warn(`Warning: WAL mode not enabled. Current mode: ${result.journal_mode}`);
            }
        }

        // Set busy timeout for concurrent access handling
        db.exec(`PRAGMA busy_timeout = ${busyTimeout};`);

        // Performance pragmas
        db.exec("PRAGMA synchronous = NORMAL;");
        db.exec(`PRAGMA cache_size = ${cacheSize};`);
        db.exec("PRAGMA temp_store = MEMORY;");

        // Check FTS5 support
        const fts5Available = checkFts5Support(db);
        if (!fts5Available) {
            // Get SQLite version for error context before closing
            const versionResult = db.query<{ version: string }, []>("SELECT sqlite_version() as version").get();
            closeDatabase(db);
            throw new MemoryError(
                ErrorCode.DB_CONNECTION_FAILED,
                "FTS5 is not available. memory requires FTS5 for full-text search.",
                { sqliteVersion: versionResult?.version ?? "unknown" }
            );
        }

        // Run quick integrity check if enabled (for existing file databases)
        if (quickCheck) {
            const result = db.query<{ quick_check: string }, []>("PRAGMA quick_check(1);").get();
            if (result?.quick_check !== "ok") {
                closeDatabase(db);
                throw new MemoryError(
                    ErrorCode.DB_CORRUPTED,
                    "Database integrity check failed",
                    { path, checkResult: result?.quick_check ?? "unknown" }
                );
            }
        }

        // Load sqlite-vec extension (optional -- vector search disabled if unavailable)
        const sqliteVecAvailable = loadSqliteVecExtension(db);

        // Apply schema
        if (applySchema) {
            createSchema(db, { sqliteVecAvailable });
        }

        return { db, walEnabled, fts5Available, sqliteVecAvailable };
    } catch (error) {
        if (error instanceof MemoryError) {
            throw error;
        }
        throw handleDbError(error);
    }
}

/**
 * Close the database connection with proper cleanup
 *
 * Finalizes live statements on factory-owned connections, then performs a
 * WAL checkpoint before closing to ensure all committed changes are
 * written to the main database file. Switches journal mode to DELETE
 * to remove WAL/SHM files that would otherwise retain OS-level locks
 * on Windows.
 *
 * initializeDatabase() re-enables WAL on the next open, so the
 * journal mode switch has no functional impact on subsequent connections.
 *
 * Native databases created outside initializeDatabase retain caller-owned
 * statement lifetimes. Their owners must finalize outstanding statements;
 * strict native close reports an error if it cannot release the connection.
 * Finalization and close failures are surfaced and can be retried.
 *
 * @param db - Database instance to close
 */
export function closeDatabase(db: Database): void {
    if (db instanceof OwnedDatabase) db.finalizeStatements();
    // Checkpoint WAL before closing
    try {
        db.exec("PRAGMA wal_checkpoint(TRUNCATE);");
    } catch {
        // Ignore errors (e.g., if not in WAL mode or :memory: database)
    }
    // Switch to DELETE journal mode to remove WAL/SHM files.
    try {
        db.exec("PRAGMA journal_mode = DELETE;");
    } catch {
        // Ignore errors (e.g., if database is read-only)
    }
    db.close(true);
}

/**
 * Perform a passive WAL checkpoint
 *
 * Checkpoints as much of the WAL as possible without blocking.
 * Use this for periodic checkpointing during long operations.
 *
 * @param db - Database instance to checkpoint
 */
export function checkpointDatabase(db: Database): void {
    db.exec("PRAGMA wal_checkpoint(PASSIVE);");
}

/**
 * Result of a WAL checkpoint operation
 */
export interface CheckpointResult {
    /** Number of WAL frames that could not be checkpointed (busy) */
    busy: number;
    /** Total number of frames in the WAL file */
    log: number;
    /** Number of frames successfully checkpointed */
    checkpointed: number;
}

/**
 * Perform a truncating WAL checkpoint after bulk operations
 *
 * Uses TRUNCATE mode which:
 * 1. Checkpoints all frames from WAL to main database
 * 2. Truncates the WAL file to zero size
 * 3. May block briefly if other connections are active
 *
 * Call this after bulk insert operations to:
 * - Reduce WAL file size
 * - Ensure all changes are in main database file
 * - Optimize subsequent read performance
 *
 * @param db - Database instance to checkpoint
 * @returns Checkpoint result with frame counts
 */
export function bulkOperationCheckpoint(db: Database): CheckpointResult {
    const result = db.query<{ busy: number; log: number; checkpointed: number }, []>(
        "PRAGMA wal_checkpoint(TRUNCATE);"
    ).get();

    return result ?? { busy: 0, log: 0, checkpointed: 0 };
}

/**
 * Initialize a database with error wrapping
 *
 * Wraps initializeDatabase and ensures all errors are MemoryError instances.
 * Use this for CLI entry points where structured error handling is needed.
 *
 * @param config - Database configuration options
 * @returns Database instance with initialization status
 * @throws MemoryError for any initialization failure
 *
 * @example
 * ```typescript
 * try {
 *     const { db } = initializeDatabaseSafe({ path: "./data/memory.db" });
 * } catch (error) {
 *     if (error instanceof MemoryError) {
 *         console.error(`[${error.code}] ${error.message}`);
 *     }
 * }
 * ```
 */
export function initializeDatabaseSafe(config: DatabaseConfig): DatabaseInitResult {
    try {
        return initializeDatabase(config);
    } catch (error) {
        // Already a MemoryError, rethrow
        if (error instanceof MemoryError) {
            throw error;
        }

        // Wrap generic errors
        const message = unknownErrorMessage(error);
        const errno = (error as NodeJS.ErrnoException).code;
        throw new MemoryError(
            ErrorCode.DB_CONNECTION_FAILED,
            `Database initialization failed: ${message}`,
            { path: config.path, ...(errno ? { errno } : {}) }
        );
    }
}

import { describe, expect, it } from "bun:test";
import { existsSync, rmSync } from "node:fs";
import { join } from "node:path";
import { setImmediate, setTimeout } from "node:timers/promises";
import { type Statement } from "bun:sqlite";
import { createOwnedTestDirectory } from "../../../tests/helpers/owned-test-directory.js";
import { createTestDatabase } from "../../../tests/helpers/test-database.js";
import { closeDatabase, initializeDatabase } from "./connection.js";
import { OwnedDatabase } from "./owned-database.js";

describe("owned native database closure", () => {
  it("finalizes a retained prepared statement and releases the database immediately", () => {
    const storage = createOwnedTestDirectory("memory-native-close-");
    const path = join(storage.dir, "database.db");
    const { db } = initializeDatabase({ path, applySchema: false, walMode: false });
    db.exec("CREATE TABLE example(value INTEGER); INSERT INTO example VALUES (1);");
    const statement = db.prepare("SELECT value FROM example");
    expect(statement.get()).toEqual({ value: 1 });
    try {
      closeDatabase(db);
      expect(() => statement.get()).toThrow();
      rmSync(path, { force: false });
      expect(existsSync(path)).toBe(false);
      expect(() => closeDatabase(db)).not.toThrow();
    } finally {
      statement.finalize();
      db.close();
      storage.cleanup();
    }
  });

  it("owns retained query-cache overflow and explicitly finalized statements", () => {
    const fixture = createTestDatabase({ applySchema: false, walMode: false });
    const statements: Statement[] = [];
    try {
      for (let value = 0; value < 128; value++) {
        const statement = fixture.db.query(`SELECT ${value} AS value`);
        expect(statement.get()).toEqual({ value });
        statements.push(statement);
      }
      statements[0]!.finalize();
      closeDatabase(fixture.db);
      for (const statement of statements) expect(() => statement.get()).toThrow();
      rmSync(fixture.path, { force: false });
    } finally {
      for (const statement of statements) statement.finalize();
      fixture.cleanup();
    }
  });

  it("preserves committed transactions and rolls back unfinished transactions", () => {
    const fixture = createTestDatabase({ applySchema: false, walMode: true });
    let reopened: ReturnType<typeof initializeDatabase> | undefined;
    const statement = fixture.db.prepare("SELECT 1 AS value");
    try {
      fixture.db.exec("CREATE TABLE example(value INTEGER);");
      fixture.db.transaction(() => fixture.db.exec("INSERT INTO example VALUES (11);"))();
      fixture.db.exec("BEGIN; INSERT INTO example VALUES (12);");
      closeDatabase(fixture.db);
      expect(() => statement.get()).toThrow();
      reopened = initializeDatabase({ path: fixture.path, create: false, applySchema: false });
      expect(reopened.db.query("SELECT value FROM example").all()).toEqual([{ value: 11 }]);
      closeDatabase(reopened.db);
      rmSync(fixture.path, { force: false });
    } finally {
      statement.finalize();
      if (reopened) closeDatabase(reopened.db);
      fixture.cleanup();
    }
  });

  it("closes only its own connection while another database stays usable", () => {
    const first = createTestDatabase({ applySchema: false, walMode: false });
    const second = createTestDatabase({ applySchema: false, walMode: false });
    const firstStatement = first.db.prepare("SELECT 1 AS value");
    const secondStatement = second.db.prepare("SELECT 2 AS value");
    try {
      closeDatabase(first.db);
      expect(() => firstStatement.get()).toThrow();
      expect(secondStatement.get()).toEqual({ value: 2 });
      rmSync(first.path, { force: false });
      closeDatabase(second.db);
      expect(() => secondStatement.get()).toThrow();
      rmSync(second.path, { force: false });
    } finally {
      firstStatement.finalize(); secondStatement.finalize();
      first.cleanup(); second.cleanup();
    }
  });

  it("does not create a missing database when create is false", () => {
    const storage = createOwnedTestDirectory("memory-native-no-create-");
    const path = join(storage.dir, "missing.db");
    try {
      expect(() => initializeDatabase({ path, create: false, applySchema: false })).toThrow();
      expect(existsSync(path)).toBe(false);
    } finally { storage.cleanup(); }
  });

  for (const failure of [new Error("synthetic finalizer failure"), "non-error finalizer failure"]) {
    it(`reports finalizer failures, attempts other statements, and permits retry: ${String(failure)}`, () => {
      const fixture = createTestDatabase({ applySchema: false, walMode: false });
      const failed = fixture.db.prepare("SELECT 1 AS value");
      const healthy = fixture.db.prepare("SELECT 2 AS value");
      const original = failed.finalize.bind(failed);
      failed.finalize = () => { throw failure; };
      try {
        let result: unknown;
        try { closeDatabase(fixture.db); } catch (error) { result = error; }
        expect(result).toBeInstanceOf(AggregateError);
        expect((result as AggregateError).errors).toEqual([failure]);
        expect(() => healthy.get()).toThrow();
        expect(failed.get()).toEqual({ value: 1 });
        failed.finalize = original;
        closeDatabase(fixture.db);
        expect(() => failed.get()).toThrow();
        rmSync(fixture.path, { force: false });
      } finally {
        failed.finalize = original;
        failed.finalize(); healthy.finalize();
        fixture.cleanup();
      }
    });
  }

  it("preserves native close failure and permits a subsequent close", () => {
    const fixture = createTestDatabase({ applySchema: false, walMode: false });
    const statement = fixture.db.prepare("SELECT 1 AS value");
    const original = fixture.db.close.bind(fixture.db), failure = new Error("native close failed");
    fixture.db.close = () => { throw failure; };
    try {
      expect(() => closeDatabase(fixture.db)).toThrow(failure);
      expect(() => statement.get()).toThrow();
      fixture.db.close = original;
      closeDatabase(fixture.db);
      rmSync(fixture.path, { force: false });
    } finally {
      fixture.db.close = original;
      statement.finalize();
      fixture.cleanup();
    }
  });

  it("does not keep an otherwise discarded statement alive", async () => {
    const fixture = createTestDatabase({ applySchema: false, walMode: false });
    const references = await (async () => {
      const statement = fixture.db.prepare("SELECT 1 AS value");
      return { wrapper: new WeakRef(statement), native: new WeakRef(statement.native as object) };
    })();
    try {
      for (let attempt = 0; attempt < 10; attempt++) {
        await setImmediate();
        Bun.gc(true);
        await setTimeout(10);
        if (references.wrapper.deref() === undefined && references.native.deref() === undefined) break;
      }
      expect(references.wrapper.deref()).toBeUndefined();
      expect(references.native.deref()).toBeUndefined();
      closeDatabase(fixture.db);
      rmSync(fixture.path, { force: false });
    } finally { fixture.cleanup(); }
  });

  it("finalizes a native resource even after its JavaScript wrapper is collected", async () => {
    const fixture = createTestDatabase({ applySchema: false, walMode: false });
    const resource = await (async () => {
      const statement = fixture.db.prepare("SELECT 1 AS value");
      return {
        wrapper: new WeakRef(statement),
        native: statement.native as { get(): unknown; finalize(): void },
      };
    })();
    try {
      for (let attempt = 0; attempt < 10; attempt++) {
        await setImmediate();
        Bun.gc(true);
        await setTimeout(10);
        if (resource.wrapper.deref() === undefined) break;
      }
      expect(resource.wrapper.deref()).toBeUndefined();
      expect(resource.native.get()).toEqual({ value: 1 });
      (fixture.db as OwnedDatabase).finalizeStatements();
      expect(() => resource.native.get()).toThrow();
      closeDatabase(fixture.db);
      rmSync(fixture.path, { force: false });
    } finally {
      resource.native.finalize();
      fixture.cleanup();
    }
  });
});

import { it, expect } from 'bun:test';
import { Database } from 'bun:sqlite';
import { rmSync } from 'node:fs';
import { join } from 'node:path';
import { createOwnedTestDirectory } from '../tests/helpers/owned-test-directory';
import { initializeDatabase, closeDatabase } from '../src/infrastructure/database/connection';
import { SqliteStatsService } from '../src/infrastructure/database/services/stats-service';
import { setImmediate } from 'node:timers/promises';

it('explicit native finalization of a table-valued pragma',()=>{
 const storage=createOwnedTestDirectory('memory-native-pragma-');
 try {
  for(let i=0;i<100;i++){
   const path=join(storage.dir,`probe-${i}.db`),db=new Database(path,{create:true});
   const stmt=db.prepare('SELECT page_size * page_count AS size FROM pragma_page_count(), pragma_page_size()');
   try{stmt.get();stmt.finalize();db.close(true);rmSync(path);}
   finally{stmt.finalize();db.close();}
  }
  expect(true).toBe(true);
 }finally{storage.cleanup();}
});

for(const retain of [false,true])it(`discarded query pressure; retain wrappers=${retain}`,async()=>{
 const storage=createOwnedTestDirectory('memory-native-pressure-');
 try {
  for(let i=0;i<20;i++){
   const path=join(storage.dir,`probe-${i}.db`),{db}=initializeDatabase({path,applySchema:false,walMode:false});
   const retained:any[]=[];
   try{
    for(let j=0;j<500;j++){
     const statement=db.prepare('SELECT 1 AS value');statement.get();if(retain)retained.push(statement);
     if(j%100===0){await setImmediate();Bun.gc(false);}
    }
    await setImmediate();Bun.gc(false);
    const references=Reflect.get(db,'statements') as Set<{wrapper:WeakRef<object>,native:WeakRef<object>}>;
    const snapshot={tracked:references.size,wrapper:0,native:0};
    for(const ref of references){if(ref.wrapper.deref())snapshot.wrapper++;if(ref.native.deref())snapshot.native++;}
    try{closeDatabase(db);rmSync(path);}catch(error){console.error('NATIVE_PRESSURE_FAILURE '+JSON.stringify({retain,iteration:i,snapshot,error:String(error)}));throw error;}
   }finally{for(const stmt of retained)stmt.finalize();db.close();}
  }
  expect(true).toBe(true);
 }finally{storage.cleanup();}
});

for(const retain of [false,true])it(`full schema and stats close; retain wrappers=${retain}`,async()=>{
 const storage=createOwnedTestDirectory('memory-native-stats-');
 try {
  for(let i=0;i<20;i++){
   const path=join(storage.dir,`probe-${i}.db`),{db}=initializeDatabase({path});
   const retained:any[]=[],prepare=db.prepare.bind(db);
   if(retain)db.prepare=function(...args:any[]){const statement=Reflect.apply(prepare,this,args);retained.push(statement);return statement;} as typeof db.prepare;
   try{await new SqliteStatsService(db).getStats();closeDatabase(db);rmSync(path);}
   finally{for(const stmt of retained)stmt.finalize();db.close();}
  }
  expect(true).toBe(true);
 }finally{storage.cleanup();}
});

import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const storage=createOwnedTestDirectory('memory-native-compat-');
const url='https://github.com/oven-sh/bun/releases/download/bun-v1.3.14/bun-windows-x64.zip';
const digest='0a0620930b6675d7ba440e81f4e0e00d3cfbe096c4b140d3fff02205e9e18922';
const archive=join(storage.dir,'bun.zip'),destination=join(storage.dir,'runtime');
const sourcePaths=['src/infrastructure/database/owned-database.ts','src/infrastructure/database/connection.ts','src/infrastructure/database/connection-lifecycle.test.ts'];
const runs:unknown[]=[];
try{
 const response=await fetch(url);if(!response.ok)throw Error('Runtime download HTTP '+response.status);
 const bytes=Buffer.from(await response.arrayBuffer());
 if(bytes.length!==38366737||createHash('sha256').update(bytes).digest('hex')!==digest)throw Error('Runtime release digest/size mismatch');
 writeFileSync(archive,bytes);mkdirSync(destination);
 const script=join(storage.dir,'expand.ps1');
 writeFileSync(script,'param([string]$Archive,[string]$Destination)\n$ErrorActionPreference = "Stop"\nExpand-Archive -LiteralPath $Archive -DestinationPath $Destination\n');
 const expanded=Bun.spawnSync(['powershell.exe','-NoProfile','-NonInteractive','-File',script,archive,destination],{stdout:'pipe',stderr:'pipe',timeout:45000});
 if(expanded.exitCode!==0)throw Error(new TextDecoder().decode(expanded.stderr));
