import {sourceHash,discoverInventory,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/', read=(path:string)=>JSON.parse(readFileSync(path,'utf8'));
const path=root+'evidence/B11.74-weak-tracking-rejection.json',record=read(path);
for(const snapshot of record.sources)assert.equal(sourceHash(snapshot.content),snapshot.sourceHash,'Preserved candidate hash mismatch');
const catalog=discoverInventory(process.cwd()),baseline=read(root+'executable-catalog.json');
assert.equal(catalog.files.length,446);assert.equal(catalog.packages.length,2);
for(const file of catalog.files){const prior=baseline.files.find((row:any)=>row.path===file.path);assert(prior,'Unexpected executable source');assert.equal(file.sourceHash,prior.sourceHash,`Changed executable source ${file.path}`);}
assert.deepEqual(validateInventory(catalog,read(root+'quality-classifications.json')),[]);
const ledger=read(root+'work-items.json'),items=new Map<string,any>(ledger.items.map((item:any)=>[item.id,item])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency');if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,225);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74');assert.deepEqual(ledger.items.filter((item:any)=>item.status==='active').map((item:any)=>item.id),['B11.74']);
for(const id of ['B11.1','B11.4'])assert(items.get(id).depends_on.includes('B11.74'));
for(const temporary of record.temporaryRoots)assert.equal(existsSync(temporary.path),false,'Retained temporary runtime root');
const currentProbe=record.sources.find((row:any)=>row.path==='.git/b11-native-resource-probe.test.ts');
assert(currentProbe.content.includes('NATIVE_PRESSURE_FAILURE'));
